using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with default reflection-based resolution
var options = new JsonSerializerOptions
{
    TypeInfoResolver = JsonSerializer.IsReflectionEnabledByDefault
        ? new DefaultJsonTypeInfoResolver()
        : null,
    WriteIndented = true
};

// ── 1. Strongly-typed metadata retrieval ──
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Type handled : {personInfo.Type.Name}");
Console.WriteLine($"Kind         : {personInfo.Kind}");
Console.WriteLine($"Properties   : {personInfo.Properties.Count}");
Console.WriteLine();

// Round-trip with the typed info
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized   : {json}");

var alice = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized : Name={alice.Name}, Age={alice.Age}");
Console.WriteLine();

// ── 2. Probe without throwing ──
// TryGetTypeInfo returns false instead of throwing when
// metadata isn't available for a type.
if (options.TryGetTypeInfo(typeof(Person), out var found))
    Console.WriteLine($"Person   : metadata available ({found!.Type.Name})");
else
    Console.WriteLine("Person   : no metadata");

// Use an empty resolver so nothing is resolvable
var empty = new JsonSerializerOptions { TypeInfoResolver = null! };

if (empty.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("Person (empty): metadata available");
else
    Console.WriteLine("Person (empty): no metadata  ← expected");

